const scamShieldSteps = [
  { key: "intake", number: "15", label: "Journey Report" },
  { key: "risk", number: "16", label: "Scam Risk Results" },
  { key: "assets", number: "17", label: "Next Steps" },
  { key: "agency", number: "18", label: "Agency Reports" },
] as const;

type ScamShieldStep = (typeof scamShieldSteps)[number]["key"];

function ScamShieldFrame({
  title,
  subtitle,
  step,
  backHref,
  children,
}: {
  title: string;
  subtitle: string;
  step: ScamShieldStep;
  backHref: Route;
  children: React.ReactNode;
}) {
  const activeStepIndex = scamShieldSteps.findIndex((item) => item.key === step);

  return (
    <div className="px-2 pb-3 pt-2 sm:px-4 sm:pb-5 sm:pt-4">
      <div className="mx-auto w-full max-w-[1184px]">
        <div className="flex items-center justify-between border-b border-[#d9e2ee] px-1 py-2">
          <Link
            href={backHref}
            className="inline-flex items-center gap-2 text-xs font-semibold text-[#1f2937]"
          >
            <IconChevronLeft size={14} />
            ScamShield
          </Link>
          <Link href="/dashboard" className="text-xs font-medium text-[#7b8798]">
            Cancel
          </Link>
        </div>

        <article className="mt-3 rounded-[16px] border border-[#dce4ef] bg-white p-4 shadow-[0_10px_24px_rgba(15,23,42,0.04)] sm:p-5">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-[0.12em] text-[#0f5d9f]">
                ScamShield
              </p>
              <h2 className="mt-1 text-[28px] font-extrabold leading-[1.02] text-[#1f2a3a] sm:text-[34px]">
                {title}
              </h2>
              <p className="mt-1 text-xs text-[#6a7d94]">{subtitle}</p>
            </div>

            <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
              {scamShieldSteps.map((item, index) => (
                <div
                  key={item.key}
                  className={cn(
                    "rounded-xl px-3 py-2 text-center",
                    index <= activeStepIndex ? "bg-[#eaf2ff]" : "bg-[#f3f6fb]"
                  )}
                >
                  <p
                    className={cn(
                      "text-[11px] font-extrabold",
                      index <= activeStepIndex ? "text-[#0f5d9f]" : "text-[#8fa0b6]"
                    )}
                  >
                    {item.number}
                  </p>
                  <p className="mt-0.5 text-[9px] font-semibold text-[#60728a]">
                    {item.label}
                  </p>
                </div>
              ))}
            </div>
          </div>

          {children}
        </article>
      </div>
    </div>
  );
}

